'use strict';
const KEY='memo.collection.v1',DAY=86400000,$=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),uid=()=>crypto.randomUUID?crypto.randomUUID():Date.now().toString(36)+Math.random().toString(36).slice(2),today=()=>new Date().toLocaleDateString('sv-SE');
function fresh(){let d=[{id:'welcome',name:'Premiers pas',description:'Découvrez votre nouvelle routine'},{id:'english',name:'Anglais · au quotidien',description:'Les mots qui ouvrent des portes'}];return {version:1,decks:d,cards:[['welcome','Comment bien réviser une carte ?','Essayez de retrouver la réponse avant de la retourner. L’effort de rappel aide la mémorisation.'],['welcome','À quoi sert la répétition espacée ?','À revoir une information au bon moment, avec des intervalles qui s’allongent lorsque vous la retenez.'],['welcome','Comment garder mes cartes en sécurité ?','Dans Réglages & sauvegarde, exportez régulièrement votre collection au format JSON.'],['english','To look forward to','Avoir hâte de.\nExemple : I look forward to seeing you.'],['english','A little goes a long way.','Un petit effort peut faire une grande différence.'],['english','Eventually','Finalement / à terme (et non « éventuellement »).']].map(([deck,front,back])=>({id:uid(),deck,front,back,tags:'exemple',due:0,interval:0,reps:0,ease:2.5,suspended:false})),logs:[],settings:{dark:false}}}
let db;try{db=JSON.parse(localStorage.getItem(KEY))||fresh()}catch(e){db=fresh();setTimeout(()=>toast('Stockage illisible : importez votre sauvegarde si nécessaire.'),100)}
let page='home',session=null,undo=null,filter='',deckFilter='',saveFailed=false;
function save(){try{localStorage.setItem(KEY,JSON.stringify(db));saveFailed=false;return true}catch(e){saveFailed=true;toast('Sauvegarde impossible. Exportez vos données maintenant.');return false}}
function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').style.display='none',4500)}
const due=c=>!c.suspended&&c.due<=Date.now(),pending=()=>db.cards.filter(due),reviewed=()=>db.logs.filter(l=>l.date===today()).length;
function go(p){page=p;session=p==='study'?session:null;render()}
function render(){document.body.classList.toggle('dark',db.settings.dark);document.querySelectorAll('[data-page]').forEach(b=>b.classList.toggle('active',b.dataset.page===page));$('#breadcrumb').textContent='Mon espace / '+({home:'Mes paquets',browse:'Mes cartes',stats:'Statistiques',settings:'Réglages',study:'Révision'}[page]||'');$('#main').innerHTML=({home:home,browse:browse,stats:stats,settings:settings,study:study}[page])();bind()}
function home(){let n=pending().length;return `<div class="topline"><div><div class="eyebrow">VOTRE RENDEZ-VOUS AVEC LA MÉMOIRE</div><h1>Un peu chaque jour.</h1><p>Retrouvez vos idées. Faites grandir vos connaissances.</p></div><button class="primary" id="newdeck">＋ Nouveau paquet</button></div><section class="hero"><div><div class="eyebrow">${n?'PRÊT POUR UNE PETITE SESSION ?':'VOUS ÊTES À JOUR'}</div><h2>${n?`${n} cartes vous attendent.`:'Une belle avance sur demain.'}</h2><p>${n?'Quelques minutes de concentration aujourd’hui, des connaissances qui restent demain.':'Ajoutez de nouvelles cartes ou revenez quand vos prochaines révisions seront prêtes.'}</p><button class="lime" id="start">${n?'Commencer la révision　 →':'Ajouter une carte　＋'}</button></div><div class="card-art" aria-hidden="true"></div></section><div class="metrics"><div class="metric"><div><label>À réviser aujourd’hui</label><b>${n}</b></div><span>◷</span></div><div class="metric"><div><label>Réponses aujourd’hui</label><b>${reviewed()}</b></div><span>✓</span></div><div class="metric"><div><label>Cartes dans ma collection</label><b>${db.cards.length}</b></div><span>▤</span></div></div><div class="section-title"><h2>Mes paquets <small>　${db.decks.length} paquets</small></h2><button class="quiet" id="import">↓ Importer</button></div><div class="decks">${db.decks.map(d=>{let cs=db.cards.filter(c=>c.deck===d.id),nw=cs.filter(c=>due(c)&&!c.reps).length,rv=cs.filter(c=>due(c)&&c.reps).length;return `<article class="deck"><div class="row"><span class="deck-icon">${d.id==='english'?'Aa':'▱'}</span><button class="quiet" data-editdeck="${d.id}" aria-label="Modifier ${esc(d.name)}">•••</button></div><h3>${esc(d.name)}</h3><p>${esc(d.description||'Votre prochain savoir commence ici.')} · ${cs.length} cartes</p><div class="deck-bottom"><div class="counts"><span class="new">${nw} nouvelles</span><b>${rv} à revoir</b></div><button data-study="${d.id}">${nw+rv?'Réviser →':'Ouvrir →'}</button></div></article>`}).join('')||'<div class="empty">Créez votre premier paquet pour commencer.</div>'}</div>`}
function browse(){let cs=db.cards.filter(c=>(!deckFilter||c.deck===deckFilter)&&[c.front,c.back,c.tags].join(' ').toLowerCase().includes(filter.toLowerCase()));return `<div class="topline"><div><div class="eyebrow">LA BIBLIOTHÈQUE DE VOS IDÉES</div><h1>Mes cartes</h1><p>Créez, retrouvez et affinez ce que vous apprenez.</p></div><button class="primary" id="addcard">＋ Ajouter</button></div><div class="toolbar"><input type="search" id="search" placeholder="Rechercher une carte, un mot-clé…" value="${esc(filter)}" aria-label="Rechercher"><select id="deckfilter" aria-label="Filtrer par paquet"><option value="">Tous les paquets</option>${options(deckFilter)}</select></div><div class="table-wrap"><table class="table"><thead><tr><th>Recto</th><th>Paquet</th><th>État</th><th></th></tr></thead><tbody>${cs.map(c=>`<tr><td>${esc(c.front.slice(0,100))}</td><td>${esc(db.decks.find(d=>d.id===c.deck)?.name)}</td><td><span class="tag">${c.suspended?'Suspendue':!c.reps?'Nouvelle':due(c)?'À revoir':new Date(c.due).toLocaleDateString('fr-FR')}</span></td><td><button data-edit="${c.id}">Modifier</button></td></tr>`).join('')}</tbody></table></div>${cs.length?'':'<div class="empty">Aucune carte pour le moment.</div>'}`}
function options(id){return db.decks.map(d=>`<option value="${d.id}" ${id===d.id?'selected':''}>${esc(d.name)}</option>`).join('')}
function modal(html){$('#modal').innerHTML=html;$('#modal').showModal();$('#modal').querySelector('[data-close]')?.addEventListener('click',()=>$('#modal').close())}
function editDeck(id){let d=db.decks.find(x=>x.id===id);modal(`<div class="row"><h2>${d?'Modifier le paquet':'Un nouveau départ'}</h2><button class="quiet" data-close aria-label="Fermer">✕</button></div><form id="deckform"><label class="field">Nom du paquet<input name="name" required maxlength="100" value="${esc(d?.name||'')}" autofocus></label><label class="field">Description<input name="description" maxlength="160" value="${esc(d?.description||'')}"></label><div class="row">${d?'<button type="button" class="danger" id="deletedeck">Supprimer</button>':''}<button class="primary">Enregistrer</button></div></form>`);$('#deckform').onsubmit=e=>{e.preventDefault();let f=new FormData(e.target),name=f.get('name').trim();if(!name)return;let val={name,description:f.get('description').trim()};if(d)Object.assign(d,val);else db.decks.push({id:uid(),...val});save();$('#modal').close();render()};if(d)$('#deletedeck').onclick=()=>{if(confirm(`Supprimer « ${d.name} » et ses cartes ?`)){db.decks=db.decks.filter(x=>x.id!==id);db.cards=db.cards.filter(x=>x.deck!==id);save();$('#modal').close();render()}}}
function editCard(id){if(!db.decks.length){editDeck();toast('Créez d’abord un paquet.');return}let c=db.cards.find(x=>x.id===id);modal(`<div class="row"><h2>${c?'Modifier la carte':'Une idée à retenir'}</h2><button class="quiet" data-close aria-label="Fermer">✕</button></div><form id="cardform"><label class="field">Paquet<select name="deck">${options(c?.deck||deckFilter)}</select></label><label class="field">Recto · question<textarea name="front" required maxlength="20000" placeholder="Que souhaitez-vous retenir ?">${esc(c?.front||'')}</textarea></label><label class="field">Verso · réponse<textarea name="back" required maxlength="20000" placeholder="La réponse, avec vos mots…">${esc(c?.back||'')}</textarea></label><label class="field">Mots-clés<input name="tags" value="${esc(c?.tags||'')}" placeholder="vocabulaire, chapitre-1"></label><label><input type="checkbox" name="suspended" ${c?.suspended?'checked':''}> Suspendre les révisions de cette carte</label><div class="row">${c?'<button type="button" class="danger" id="deletecard">Supprimer</button>':''}<button class="primary">Enregistrer</button></div></form>`);$('#cardform').onsubmit=e=>{e.preventDefault();let f=new FormData(e.target),v={deck:f.get('deck'),front:f.get('front').trim(),back:f.get('back').trim(),tags:f.get('tags').trim(),suspended:f.has('suspended')};if(!v.front||!v.back)return;if(c)Object.assign(c,v);else db.cards.push({id:uid(),due:0,interval:0,reps:0,ease:2.5,...v});save();$('#modal').close();render();toast('Carte enregistrée')};if(c)$('#deletecard').onclick=()=>{if(confirm('Supprimer cette carte ?')){db.cards=db.cards.filter(x=>x.id!==id);save();$('#modal').close();render()}}}
function start(deck){let q=db.cards.filter(c=>due(c)&&(!deck||c.deck===deck)).sort((a,b)=>a.due-b.due).map(c=>c.id);if(!q.length){deckFilter=deck||'';go('browse');return}session={queue:q,total:q.length,done:0,reveal:false,deck};undo=null;go('study')}
function schedule(c,r,now=Date.now()){let next={...c};if(r===0){next.interval=0;next.due=now+60000;next.ease=Math.max(1.3,c.ease-.2)}else{let i=c.interval||1;next.interval=r===1?Math.max(1,Math.round(i*1.2)):r===2?(c.reps?Math.max(1,Math.round(i*c.ease)):1):(c.reps?Math.max(4,Math.round(i*c.ease*1.3)):4);next.ease=Math.max(1.3,c.ease+(r===1?-.15:r===3?.15:0));next.due=now+next.interval*DAY}next.reps++;return next}
function study(){let c=db.cards.find(c=>c.id===session?.queue[0]);if(!c)return `<div class="study"><div class="flashcard"><small>SESSION TERMINÉE</small><div class="question">Un pas de plus.<br>Bien joué !</div><p class="muted">${session?.done||0} réponses pendant cette session.</p><button id="backhome" class="primary">Retour aux paquets</button></div>${undo?'<button id="undo">Annuler la dernière réponse</button>':''}</div>`;return `<div class="study"><div class="row"><button id="backhome" class="quiet">← Mes paquets</button><span class="muted">${session.queue.length} cartes restantes</span></div><div class="progress"><div style="width:${Math.min(100,session.done/session.total*100)}%"></div></div><div class="eyebrow">${esc(db.decks.find(d=>d.id===c.deck)?.name)}</div><div class="flashcard"><small>${session.reveal?'À VOUS DE JUGER':'PRENEZ LE TEMPS DE VOUS SOUVENIR'}</small><div class="question">${esc(c.front)}</div>${session.reveal?`<div class="answer">${esc(c.back)}</div>`:''}</div><div class="study-actions">${session.reveal?['À revoir','Difficile','Bien','Facile'].map((t,r)=>`<button data-rate="${r}" class="${r===2?'primary':''}"><small>${r===0?'1 min':schedule(c,r).interval+' j'}</small>${t}</button>`).join(''):'<button id="reveal" class="primary">Afficher la réponse</button>'}</div><p class="muted" style="text-align:center;font-size:11px">Espace : retourner · 1–4 : évaluer${undo?' · <button class="quiet" id="undo">Annuler</button>':''}</p></div>`}
function rate(r){if(!session?.reveal)return;let c=db.cards.find(c=>c.id===session.queue[0]);undo={card:{...c},session:JSON.parse(JSON.stringify(session)),logLength:db.logs.length};Object.assign(c,schedule(c,r));db.logs.push({date:today(),at:Date.now(),rating:r,card:c.id});session.queue.shift();session.done++;session.reveal=false;save();render()}
function stats(){let days=Array.from({length:7},(_,i)=>{let d=new Date();d.setDate(d.getDate()-6+i);return {label:d.toLocaleDateString('fr-FR',{weekday:'short'}),n:db.logs.filter(l=>l.date===d.toLocaleDateString('sv-SE')).length}}),max=Math.max(1,...days.map(d=>d.n));return `<div class="eyebrow">CHAQUE RÉPÉTITION COMPTE</div><h1>Vos progrès prennent forme.</h1><div class="metrics"><div class="metric"><div><label>Réponses au total</label><b>${db.logs.length}</b></div></div><div class="metric"><div><label>Cartes déjà étudiées</label><b>${db.cards.filter(c=>c.reps).length}</b></div></div><div class="metric"><div><label>Jours de pratique</label><b>${new Set(db.logs.map(l=>l.date)).size}</b></div></div></div><section class="settings-box"><h2>Vos 7 derniers jours</h2><p>Nombre de réponses enregistrées chaque jour.</p><div class="chart">${days.map(d=>`<div class="bar" style="height:${Math.max(2,d.n/max*100)}%" title="${d.n} réponses"><span>${d.label}<br>${d.n}</span></div>`).join('')}</div><div style="height:35px"></div></section>`}
function settings(){return `<div class="eyebrow">À VOTRE FAÇON</div><h1>Un espace qui vous ressemble.</h1><section class="settings-box"><h2>Votre collection vous appartient</h2><p>Les cartes restent dans ce navigateur, sur cet appareil. Exportez une sauvegarde avant de vider Safari ou de changer d’appareil. Aucun compte AnkiWeb n’est connecté.</p><div class="toolbar"><button class="primary" id="export">Exporter la sauvegarde JSON</button><button id="exporttsv">Exporter pour Anki (.tsv)</button><button id="import">Importer</button></div><p>JSON : restaure une collection Mémo complète après confirmation. TSV : ajoute des cartes (recto, verso, paquet, mots-clés séparés par des tabulations). Les fichiers .apkg ne sont pas pris en charge.</p></section><section class="settings-box"><h2>Sur votre iPad</h2><p>Ouvrez ce site dans Safari, puis Partager → Sur l’écran d’accueil. L’application peut mettre ses fichiers en cache pour une utilisation hors ligne après une première ouverture réussie ; cette possibilité dépend de l’hébergement et de Safari.</p></section><section class="settings-box"><h2>Le code est à vous</h2><p>Téléchargez les fichiers HTML, CSS et JavaScript. Modifiez-les dans un éditeur sur iPad, puis hébergez le dossier pour utiliser votre version. Le guide explique chaque étape.</p><a href="memo-sources.zip" download>Télécharger le code source ↓</a></section><section class="settings-box"><h2>Apparence</h2><p>Un environnement confortable pour vos sessions du soir.</p><button id="theme">${db.settings.dark?'Passer au thème clair':'Passer au thème sombre'}</button></section><p class="muted">Mémo est une application indépendante inspirée d’Anki. Son ordonnanceur est simplifié ; ce n’est pas FSRS. Pas de synchronisation AnkiWeb, de modules complémentaires ni de prise en charge des médias ou des cartes à trous. <a href="https://github.com/ankitects/anki" target="_blank" rel="noopener">Consulter le projet Anki</a>.</p>`}
function download(name,text,type){let url=URL.createObjectURL(new Blob([text],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),60000)}
function valid(v){if(!v||v.version!==1||!Array.isArray(v.decks)||!Array.isArray(v.cards)||!Array.isArray(v.logs)||!v.settings||typeof v.settings.dark!=='boolean')return false;let ids=new Set();for(let d of v.decks){if(typeof d.id!=='string'||! /^[a-zA-Z0-9_-]+$/.test(d.id)||ids.has(d.id)||typeof d.name!=='string'||!d.name.trim()||(d.description!==undefined&&typeof d.description!=='string'))return false;ids.add(d.id)}let cs=new Set();for(let c of v.cards){if(typeof c.id!=='string'||! /^[a-zA-Z0-9_-]+$/.test(c.id)||cs.has(c.id)||!ids.has(c.deck)||!['front','back','tags'].every(k=>typeof c[k]==='string')||!['due','interval','ease','reps'].every(k=>Number.isFinite(c[k])&&c[k]>=0)||typeof c.suspended!=='boolean')return false;cs.add(c.id)}return v.logs.every(l=>typeof l.date==='string'&&Number.isFinite(l.at)&&Number.isInteger(l.rating)&&l.rating>=0&&l.rating<=3)}
async function importFile(file){if(!file)return;try{if(file.size>20000000)throw Error('Fichier trop volumineux (20 Mo maximum).');let text=await file.text();if(file.name.endsWith('.json')){let v=JSON.parse(text);if(!valid(v))throw Error('Sauvegarde Mémo invalide.');if(!confirm('Remplacer votre collection actuelle par cette sauvegarde ? Exportez-la auparavant si vous souhaitez la conserver.'))return;db=v}else{let lines=text.replace(/^\uFEFF/,'').split(/\r?\n/).filter(x=>x.trim()&&!x.startsWith('#'));let parsed=lines.map(l=>l.split('\t'));if(!parsed.length||parsed.some(a=>a.length<2||!a[0].trim()||!a[1].trim()))throw Error('Chaque ligne doit contenir un recto et un verso séparés par une tabulation.');let n=0;for(let [front,back,name,tags] of parsed){name=name||'Cartes importées';let d=db.decks.find(d=>d.name===name);if(!d){d={id:uid(),name,description:'Import TSV'};db.decks.push(d)}db.cards.push({id:uid(),deck:d.id,front,back,tags:tags||'',due:0,interval:0,reps:0,ease:2.5,suspended:false});n++}toast(`${n} cartes importées`)}save();deckFilter='';render()}catch(e){toast(e.message)}finally{$('#file').value=''}}
function bind(){let on=(s,f)=>{let el=$(s);if(el)el.onclick=f};on('#newdeck',()=>editDeck());on('#addcard',()=>editCard());on('#start',()=>pending().length?start():editCard());on('#backhome',()=>go('home'));on('#reveal',()=>{session.reveal=true;render()});on('#undo',()=>{if(!undo)return;Object.assign(db.cards.find(c=>c.id===undo.card.id),undo.card);session=undo.session;db.logs.length=undo.logLength;undo=null;save();render()});on('#export',()=>download('memo-'+today()+'.json',JSON.stringify(db,null,2),'application/json'));on('#exporttsv',()=>{let clean=s=>String(s).replace(/[\t\r\n]+/g,' ');download('memo-cartes.tsv','#separator:Tab\n#html:false\n'+db.cards.map(c=>[c.front,c.back,db.decks.find(d=>d.id===c.deck)?.name||'',c.tags].map(clean).join('\t')).join('\n'),'text/tab-separated-values')});on('#import',()=>$('#file').click());on('#theme',()=>{db.settings.dark=!db.settings.dark;save();render()});document.querySelectorAll('[data-editdeck]').forEach(b=>b.onclick=()=>editDeck(b.dataset.editdeck));document.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>editCard(b.dataset.edit));document.querySelectorAll('[data-study]').forEach(b=>b.onclick=()=>start(b.dataset.study));document.querySelectorAll('[data-rate]').forEach(b=>b.onclick=()=>rate(Number(b.dataset.rate)));if($('#search'))$('#search').oninput=e=>{let pos=e.target.selectionStart;filter=e.target.value;render();$('#search').focus();$('#search').setSelectionRange(pos,pos)};if($('#deckfilter'))$('#deckfilter').onchange=e=>{deckFilter=e.target.value;render()}}
document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>go(b.dataset.page));$('.brand').onclick=e=>{e.preventDefault();go('home')};$('#file').onchange=e=>importFile(e.target.files[0]);document.addEventListener('keydown',e=>{if($('#modal').open||/INPUT|TEXTAREA|SELECT/.test(e.target.tagName)||page!=='study')return;if(e.code==='Space'&&!session.reveal){e.preventDefault();$('#reveal')?.click()}else if(/^[1-4]$/.test(e.key)&&session.reveal)rate(Number(e.key)-1)});render();if('serviceWorker'in navigator&&location.protocol==='https:')navigator.serviceWorker.register('./sw.js').catch(()=>{});
